CREATE VIEW dbo.IV_Q$DOC_ANALISE_CREDITO ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , TIPO_DE_CLIENTE, Q002_COPIA_ULTIMO, Q002_D_R_E_DEMONS, Q002_FATUR, Q002_CONT_SOCIAL, Q002_COMPROV_END, Q002_TELEFONE, Q002_EMAIL7, Q002_TRES_REFERENCIA, Q002_REF_BANC, Q003_DECA3, Q003_IR3, Q003_CPF3, Q003_RG3, Q003_COPIA_COMPROVA3, Q003_FONE3, Q003_EMAIL3, Q003_TRES_COM3, Q003_TRES_BANC3, Q004_CPF4, Q004_RG4, Q004_COPIA_COMPROVAN, Q004_COPIA_DO_HOLERI, Q004_FONE4, Q004_EMAIL4, Q004_TRES_COM4, Q004_TRES_BANC4)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.TIPO_DE_CLIENTE, TABF.Q002_COPIA_ULTIMO, TABF.Q002_D_R_E_DEMONS, TABF.Q002_FATUR, TABF.Q002_CONT_SOCIAL, TABF.Q002_COMPROV_END, TABF.Q002_TELEFONE, TABF.Q002_EMAIL7, TABF.Q002_TRES_REFERENCIA, TABF.Q002_REF_BANC, TABF.Q003_DECA3, TABF.Q003_IR3, TABF.Q003_CPF3, TABF.Q003_RG3, TABF.Q003_COPIA_COMPROVA3, TABF.Q003_FONE3, TABF.Q003_EMAIL3, TABF.Q003_TRES_COM3, TABF.Q003_TRES_BANC3, TABF.Q004_CPF4, TABF.Q004_RG4, TABF.Q004_COPIA_COMPROVAN, TABF.Q004_COPIA_DO_HOLERI, TABF.Q004_FONE4, TABF.Q004_EMAIL4, TABF.Q004_TRES_COM4, TABF.Q004_TRES_BANC4    FROM IV_Q_DOC_ANALISE_CREDITO TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 